"use client"

import * as React from "react"

import { useInk, useInkSeed, useMergedRef } from "@/lib/ink/react"
import { ratingRecipe, type RatingIcon } from "@/lib/ink/recipes/rating-ink"
import { cn } from "@/lib/utils"

type RatingSize = "sm" | "default" | "lg"

interface RatingContextValue {
  max: number
  allowHalf: boolean
  icon: RatingIcon
  size: RatingSize
  shown: number
  current: number
  interactive: boolean
  disabled: boolean
  readOnly: boolean
  invalid: boolean
  tabStop: number
  seed: string
  getLabel: (value: number, max: number) => string
  select: (value: number) => void
  preview: (value: number | null) => void
}

const RatingContext = React.createContext<RatingContextValue | null>(null)

function useRatingContext(): RatingContextValue {
  const c = React.useContext(RatingContext)
  if (!c) throw new Error("RatingItem must be used within <Rating>")
  return c
}

const glyph: Record<RatingSize, string> = {
  sm: "size-5",
  default: "size-6",
  lg: "size-8",
}

const clamp = (v: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, v))
const noop = (): void => {}

function RatingItem({ index, className, ref, ...props }: Omit<React.ComponentProps<"span">, "children"> & { index: number }) {
  const c = useRatingContext()
  const state = c.shown >= index ? "checked" : c.allowHalf && c.shown >= index - 0.5 ? "indeterminate" : "unchecked"
  const { hostRef, hostProps, node } = useInk({ recipe: ratingRecipe, params: { icon: c.icon, disabled: c.disabled, invalid: c.invalid }, kind: "rating", seed: `${c.seed}:${index}`, still: true })
  const values = c.allowHalf ? [index - 0.5, index] : [index]
  return (
    <span
      data-slot="rating-item"
      data-state={state}
      data-value={index}
      data-ink-focus="within"
      ref={useMergedRef<HTMLSpanElement>(hostRef, ref)}
      {...hostProps}
      className={cn(
        "relative isolate inline-block shrink-0 transition-transform duration-(--ll-dur-pop) ease-pop",
        glyph[c.size],
        c.interactive && "hover:scale-110",
        "forced-colors:before:absolute forced-colors:before:inset-0 forced-colors:before:grid forced-colors:before:place-content-center forced-colors:before:leading-none forced-colors:before:content-['☆'] forced-colors:data-[state=checked]:before:content-['★'] forced-colors:data-[state=indeterminate]:before:content-['◐']",
        className
      )}
      {...props}
    >
      {node}
      {!c.readOnly
        ? values.map((v, i) => (
            <button
              key={v}
              type="button"
              role="radio"
              data-slot="rating-radio"
              data-value={v}
              aria-checked={c.current === v}
              aria-label={c.getLabel(v, c.max)}
              tabIndex={v === c.tabStop ? 0 : -1}
              disabled={c.disabled}
              onClick={() => c.select(v)}
              onPointerEnter={(e) => {
                if (e.pointerType === "mouse") c.preview(v)
              }}
              className={cn(
                "absolute -inset-y-0.5 cursor-pointer appearance-none bg-transparent outline-hidden disabled:cursor-not-allowed",
                values.length === 1 ? "-inset-x-0.5" : i === 0 ? "-start-0.5 w-[calc(50%+2px)]" : "-end-0.5 w-[calc(50%+2px)]"
              )}
            />
          ))
        : null}
    </span>
  )
}

function Rating({
  value,
  defaultValue = 0,
  onValueChange,
  max = 5,
  allowHalf = false,
  readOnly = false,
  disabled = false,
  required,
  name,
  icon = "star",
  size = "default",
  clearable = false,
  getLabel = (v, m) => `${v} of ${m}`,
  seed: seedProp,
  className,
  children,
  onKeyDown,
  onPointerLeave,
  ref,
  ...props
}: Omit<React.ComponentProps<"div">, "defaultValue" | "children"> & {
  value?: number
  defaultValue?: number
  onValueChange?: (value: number) => void
  max?: number
  allowHalf?: boolean
  readOnly?: boolean
  disabled?: boolean
  required?: boolean
  name?: string
  icon?: RatingIcon
  size?: RatingSize
  clearable?: boolean
  getLabel?: (value: number, max: number) => string
  seed?: string | number
  children?: React.ReactNode
}) {
  const step = allowHalf ? 0.5 : 1
  const snap = (v: number): number => clamp(Math.round(v / step) * step, 0, max)
  const [inner, setInner] = React.useState(() => snap(defaultValue))
  const [hover, setHover] = React.useState<number | null>(null)
  const controlled = value !== undefined
  const current = snap(controlled ? value : inner)
  const interactive = !readOnly && !disabled
  const shown = interactive && hover !== null ? hover : current
  const seed = useInkSeed(seedProp)
  const tabStop = current > 0 ? current : step
  const invalid = props["aria-invalid"] === true || props["aria-invalid"] === "true"
  const rootRef = React.useRef<HTMLDivElement>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)

  const set = (v: number): void => {
    const next = snap(v)
    if (!controlled) setInner(next)
    if (next !== current) onValueChange?.(next)
  }

  const latest = React.useRef({ reset: () => {} })
  latest.current.reset = () => {
    const next = snap(defaultValue)
    if (!controlled) setInner(next)
    if (next !== current) onValueChange?.(next)
  }
  React.useEffect(() => {
    const form = inputRef.current?.form ?? rootRef.current?.closest("form")
    if (!form) return
    const reset = () => latest.current.reset()
    form.addEventListener("reset", reset)
    return () => form.removeEventListener("reset", reset)
  }, [name, required])

  const ctx: RatingContextValue = {
    max,
    allowHalf,
    icon,
    size,
    shown,
    current,
    interactive,
    disabled,
    readOnly,
    invalid,
    tabStop,
    seed,
    getLabel,
    select: (v) => {
      setHover(null)
      set(clearable && v === current ? 0 : v)
    },
    preview: setHover,
  }

  const items = children ?? Array.from({ length: max }, (_, i) => <RatingItem key={i} index={i + 1} />)

  return (
    <RatingContext.Provider value={ctx}>
      <div
        data-slot="rating"
        data-readonly={readOnly ? "" : undefined}
        data-disabled={disabled ? "" : undefined}
        role={readOnly ? "img" : "radiogroup"}
        aria-label={readOnly && !props["aria-label"] && !props["aria-labelledby"] ? `Rated ${current} out of ${max}` : props["aria-label"]}
        aria-required={!readOnly && required ? true : undefined}
        aria-disabled={disabled && !readOnly ? true : undefined}
        ref={useMergedRef<HTMLDivElement>(rootRef, ref)}
        className={cn("relative inline-flex items-center gap-1 align-middle", className)}
        onPointerLeave={(e) => {
          setHover(null)
          onPointerLeave?.(e)
        }}
        onKeyDown={(e) => {
          onKeyDown?.(e)
          if (e.defaultPrevented || !interactive || !(e.target as HTMLElement).matches("[role=radio]")) return
          const rtl = getComputedStyle(e.currentTarget).direction === "rtl"
          let next: number
          if (e.key === "ArrowRight") next = current + (rtl ? -step : step)
          else if (e.key === "ArrowLeft") next = current + (rtl ? step : -step)
          else if (e.key === "ArrowUp") next = current + step
          else if (e.key === "ArrowDown") next = current - step
          else if (e.key === "Home") next = step
          else if (e.key === "End") next = max
          else return
          e.preventDefault()
          next = clamp(next, step, max)
          set(next)
          e.currentTarget.querySelector<HTMLElement>(`[role=radio][data-value="${next}"]`)?.focus()
        }}
        {...props}
      >
        {items}
        {required && !readOnly ? (
          <input
            ref={inputRef}
            type="text"
            name={name}
            value={current > 0 ? current : ""}
            required
            disabled={disabled}
            tabIndex={-1}
            aria-hidden="true"
            autoComplete="off"
            onChange={noop}
            className="pointer-events-none absolute inset-0 size-full opacity-0"
          />
        ) : name ? (
          <input ref={inputRef} type="hidden" name={name} value={current} disabled={disabled} />
        ) : null}
      </div>
    </RatingContext.Provider>
  )
}

export { Rating, RatingItem }

import { blobFill, wash } from '@/lib/ink/fills'
import { TAU, seg } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { burstLines, focusRing, loopLines, starLines } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import type { Ink } from '@/lib/ink/builder'
import type { PaintKey } from '@/lib/ink/paint'
import type { Line, PenName, Pt } from '@/lib/ink/types'

export const ratingIconList = ['star', 'heart', 'sun'] as const
export type RatingIcon = (typeof ratingIconList)[number]

export interface RatingParams {
  icon?: RatingIcon
  disabled?: boolean
  invalid?: boolean
}

const FILL: Record<RatingIcon, PaintKey> = { star: 'hi', heart: 'tomato', sun: 'hi' }

function starPoly(cx: number, cy: number, R: number): Pt[] {
  const pts: Pt[] = []
  for (let i = 0; i < 10; i++) {
    const a = -Math.PI / 2 + (i * TAU) / 10
    const r = i % 2 ? R * 0.46 : R
    pts.push([cx + Math.cos(a) * r, cy + Math.sin(a) * r])
  }
  return pts
}

function heartPts(cx: number, cy: number, R: number, t0 = 0, t1 = TAU, n = 44): Pt[] {
  const pts: Pt[] = []
  for (let i = 0; i <= n; i++) {
    const t = t0 + ((t1 - t0) * i) / n
    const x = 16 * Math.sin(t) ** 3
    const y = -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t))
    pts.push([cx + (x / 17) * R * 1.02, cy + (y / 17) * R * 0.98 + R * 0.06])
  }
  return pts
}

function discPoly(cx: number, cy: number, r: number, n = 24): Pt[] {
  return Array.from({ length: n }, (_, i) => [cx + Math.cos((i / n) * TAU) * r, cy + Math.sin((i / n) * TAU) * r] as Pt)
}

function clipX(poly: Pt[], at: number, keepLow: boolean): Pt[] {
  const inside = (p: Pt): boolean => (keepLow ? p[0] <= at : p[0] >= at)
  const out: Pt[] = []
  for (let i = 0; i < poly.length; i++) {
    const a = poly[i]
    const b = poly[(i + 1) % poly.length]
    const ia = inside(a)
    const ib = inside(b)
    if (ia) out.push(a)
    if (ia !== ib) {
      const t = (at - a[0]) / (b[0] - a[0])
      out.push([at, a[1] + t * (b[1] - a[1])])
    }
  }
  return out
}

function outlineLines(ink: Ink, icon: RatingIcon, cx: number, cy: number, R: number, filled = false): Line[] {
  const rng = ink.next('outline')
  if (icon === 'star' && filled) {
    const pts = starPoly(cx, cy + R * 0.05, R * 1.02)
    pts.push(pts[0], [pts[1][0] + rng.gauss(0, 0.1), pts[1][1]])
    return [{ pts, o: { poly: true, start: 'pool', end: 'flick', wobble: 0.5 } }]
  }
  if (icon === 'star') return starLines(rng, cx, cy + R * 0.05, R * 1.02)
  if (icon === 'heart') {
    const pts = heartPts(cx, cy, R, 0.06, TAU + 0.16).map((p, i, all) => [p[0] + rng.gauss(0, 0.12) * (i / all.length), p[1]] as Pt)
    return [{ pts, o: { start: 'pool', end: 'flick', wobble: 0.6 } }]
  }
  const r = R * 0.5
  return [...loopLines(rng.fork('disc'), cx, cy, r, r, { turns: 1.1 }), ...burstLines(rng.fork('rays'), cx, cy, R * 1.02, { rays: 9 })]
}

export const ratingRecipe = defineRecipe<RatingParams>({
  id: 'rating',
  kind: 'rating',
  layers: ['rest', 'checked', 'indeterminate', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink, { w, h }, { icon = 'star', disabled, invalid }, ctx) {
    const s = Math.min(w, h)
    const cx = w / 2
    const cy = h / 2
    const R = s / 2 - 1.6
    const calm = ctx.calm
    const rtl = ctx.dir === 'rtl'
    if (!disabled) ctx.lazy('focus', (f) => focusRing(f, 0, 0, w, h, { shape: 'ellipse', gap: 3 }))
    if (ctx.lazyOnly) return

    const fine = s < 22
    const restPen: PenName = disabled ? 'pencil.fine' : invalid ? 'red' : 'pencil'
    const feltPen: PenName = disabled ? 'pencil' : calm ? 'pencil.fine' : fine ? 'ink.fine' : 'ink'
    const blob = (poly: Pt[]): void => {
      ink.part('fill', () => {
        if (disabled) return wash(ink, poly, 'pencil-mark', { alpha: 0.4, material: 'wash' })
        return blobFill(ink, poly, FILL[icon], { alpha: icon === 'heart' ? 0.84 : 0.9, mis: clamp(s * 0.05, 0.6, 1.6) })
      })
    }
    const body = (): Pt[] => (icon === 'star' ? starPoly(cx, cy + R * 0.05, R) : icon === 'heart' ? heartPts(cx, cy, R) : discPoly(cx, cy, R * 0.52))

    ink.layer('rest', () => {
      const empty = (): void => ink.lines(outlineLines(ink, icon, cx, cy, R), restPen, { width: disabled ? 0.9 : 1, alpha: disabled ? 0.6 : 0.95, simple: s < 40 })
      if (invalid && !disabled) ink.group({ hideOn: 'checked indeterminate' }, empty)
      else empty()
    })
    ink.layer('checked', () => {
      blob(body())
      ink.lines(outlineLines(ink, icon, cx, cy, R, true), feltPen, { simple: s < 30 })
    })
    ink.layer('indeterminate', () => {
      const half = clipX(body(), cx, !rtl)
      blob(half)
      ink.lines(outlineLines(ink, icon, cx, cy, R, true), feltPen, { alpha: 0.9, simple: s < 30 })
      if (!calm) ink.stroke(seg(cx + 0.2, cy - R * 0.55, cx - 0.2, cy + R * 0.7, 0.3, 3), 'pencil.fine', { alpha: 0.5, start: 'soft', end: 'soft', wobble: 0.3, simple: true })
    })
  },
})

